import{_t as e,it as t,n,rt as r}from"./chunks/framework.C5Z6qjff.js";var i=JSON.parse(`{"title":"Operations","description":"","frontmatter":{"title":"Operations","covers":{"screens":[],"stories":["US-011","US-019","US-027"]}},"headers":[],"relativePath":"administration/operations.md","filePath":"administration/operations.md"}`),a={name:`administration/operations.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to “Operations”">​</a></h1><h2 id="database-roles" tabindex="-1">Database roles <a class="header-anchor" href="#database-roles" aria-label="Permalink to “Database roles”">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Used by</th><th>Owns</th></tr></thead><tbody><tr><td><code>oea_owner</code></td><td>migration step: <code>db/migration</code>, <code>db/migration-audit</code></td><td>schemas <code>public</code>, <code>audit</code> and their objects</td></tr><tr><td><code>oea_reporting_owner</code></td><td>migration step: <code>db/migration-reporting</code></td><td>schemas <code>reporting</code>, <code>reporting_ctx</code> and their objects</td></tr><tr><td><code>oea_app</code></td><td>backend at runtime</td><td>nothing</td></tr><tr><td><code>oea_audit_cleanup</code></td><td>audit retention job</td><td>nothing</td></tr><tr><td><code>oea_auditor</code></td><td>audit verification, external auditors</td><td>nothing</td></tr><tr><td><code>oea_analytics</code></td><td>raw analytics connections</td><td>nothing</td></tr></tbody></table><p>No role is <code>SUPERUSER</code>, <code>CREATEROLE</code>, <code>CREATEDB</code> or <code>BYPASSRLS</code>, and no OEA role is a member of another OEA role. The runtime role <code>oea_app</code> holds only <code>INSERT</code> and <code>SELECT</code> on the audit tables; the backend refuses to start otherwise. You rotate role passwords by running the provisioning script again (see <a href="./../setup/installation#provisioning-once">Installation</a>).</p><h2 id="request-size-limits" tabindex="-1">Request size limits <a class="header-anchor" href="#request-size-limits" aria-label="Permalink to “Request size limits”">​</a></h2><p>Request bodies are limited before they are parsed. A larger body is answered with <code>413</code> and the problem type <code>urn:oea:problem:request-too-large</code> (<code>package-too-large</code> for metamodel packages):</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Applies to</th></tr></thead><tbody><tr><td><code>oea.web.request-size.default</code> (<code>OEA_WEB_REQUESTSIZE_DEFAULT</code>)</td><td><code>1MB</code></td><td>every operation with a request body</td></tr><tr><td><code>oea.web.request-size.entity-batch</code> (<code>OEA_WEB_REQUESTSIZE_ENTITYBATCH</code>)</td><td><code>10MB</code></td><td><code>POST /entities/batch</code></td></tr><tr><td><code>oea.metamodel.import.max-size</code> (<code>OEA_METAMODEL_IMPORT_MAXSIZE</code>)</td><td><code>10MB</code></td><td><code>POST /admin/metamodel/import</code></td></tr></tbody></table><p>A reverse proxy in front of OEA should allow at least the largest of these values.</p><h2 id="rate-limits" tabindex="-1">Rate limits <a class="header-anchor" href="#rate-limits" aria-label="Permalink to “Rate limits”">​</a></h2><p>Every logged-in person and system admin account may send a limited number of requests per minute. The minute starts with the first request; a request above the limit is answered with <code>429</code>, the problem type <code>urn:oea:problem:too-many-requests</code> and the header <code>Retry-After</code> with the seconds until the next request is accepted. Nothing of a rejected request is processed, and other users are not affected.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Applies to</th></tr></thead><tbody><tr><td><code>oea.web.rate-limit.requests-per-minute</code> (<code>OEA_WEB_RATELIMIT_REQUESTSPERMINUTE</code>)</td><td><code>600</code></td><td>every request of a logged-in principal</td></tr><tr><td><code>oea.web.rate-limit.entity-batch-per-minute</code> (<code>OEA_WEB_RATELIMIT_ENTITYBATCHPERMINUTE</code>)</td><td><code>10</code></td><td><code>POST /entities/batch</code>, in addition to the request limit</td></tr></tbody></table><p>Both values must be at least <code>1</code>; otherwise the backend does not start. The first rejection of a principal within a minute is recorded in the audit trail as <code>auth.throttled</code> with the scope <code>principal</code>.</p><p>The counters are kept in the memory of the backend. If you run several backend instances behind a load balancer, each instance counts on its own, so a principal can send up to the limit times the number of instances. After a restart, the counting starts again.</p><p>Logins and the setup page are throttled separately per login name and source address (100 failed attempts within 10 minutes). A rate-limiting reverse proxy in front of OEA is a useful additional layer when the instance is reachable from the internet; it does not replace these limits.</p><h2 id="key-encryption-key" tabindex="-1">Key-encryption key <a class="header-anchor" href="#key-encryption-key" aria-label="Permalink to “Key-encryption key”">​</a></h2><p>Stored secrets – TOTP secrets and client secrets of identity providers – are encrypted with AES-256-GCM under the key-encryption key, a file outside the database. Every encrypted value records the ID of its key (the first 16 hex digits of the key&#39;s SHA-256).</p><ul><li><code>oea.security.kek.current</code> (<code>OEA_SECURITY_KEK_CURRENT</code>) names the key file; the Compose setup mounts the file named by <code>OEA_KEK_FILE</code> as the secret <code>/run/secrets/oea_kek</code>.</li><li>Keep the key out of database backups and store it separately. A database dump without the key does not reveal the secrets – and without the key, the secrets are lost.</li></ul><h3 id="rotate-the-key" tabindex="-1">Rotate the key <a class="header-anchor" href="#rotate-the-key" aria-label="Permalink to “Rotate the key”">​</a></h3><ol><li><p>Create a new key file and configure it as <code>oea.security.kek.current</code>; configure the old one as <code>oea.security.kek.previous</code> (a list of files, <code>OEA_SECURITY_KEK_PREVIOUS</code>).</p></li><li><p>Re-encrypt all stored secrets with the runtime credentials:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oea-backend.jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secrets</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reencrypt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --spring.datasource.url=jdbc:postgresql://db.example.org:5432/oea</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --spring.datasource.username=oea_app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --spring.datasource.password=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA_APP_PASSWORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --oea.security.kek.current=/run/secrets/oea_kek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --oea.security.kek.previous=/run/secrets/oea_kek_previous</span></span></code></pre></div></li><li><p>Remove the old key from the configuration and destroy it.</p></li></ol><p>The command re-encrypts in one transaction and prints <code>OK &lt;n&gt; secret(s) re-encrypted with key &lt;key ID&gt;</code>. Exit codes: <code>0</code> done, <code>1</code> a value could not be decrypted with the configured keys (nothing was changed), <code>2</code> usage or connection error.</p><h2 id="log-format" tabindex="-1">Log format <a class="header-anchor" href="#log-format" aria-label="Permalink to “Log format”">​</a></h2><p>The backend and its commands log to the console as plain text. For a log platform or SIEM, switch to JSON lines in one of the formats <code>ecs</code> (Elastic Common Schema), <code>logstash</code> or <code>gelf</code> (Graylog):</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># .env of the Compose installation</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OEA_LOG_FORMAT</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ecs</span></span></code></pre></div><p>Without Compose, set the environment variable <code>LOGGING_STRUCTURED_FORMAT_CONSOLE</code> (or the option <code>--logging.structured.format.console=ecs</code>). An empty value keeps plain text.</p><ul><li>Every JSON line carries timestamp, level, logger and message. An entry written during an HTTP request also has the field <code>requestId</code>, the same value as the <code>X-Request-Id</code> header and the request ID of the audit record.</li><li>No entry contains passwords, setup tokens, second-factor secrets or session tokens, in any format.</li><li>Checkpoint entries keep their message and get the fields <code>event</code>, <code>chainSeq</code>, <code>recordHash</code> and <code>at</code>. GELF prefixes them with <code>_</code>. <code>audit verify --checkpoints</code> reads checkpoints from plain text and JSON lines, also mixed in one file (see below).</li></ul><h2 id="password-login-of-persons" tabindex="-1">Password login of persons <a class="header-anchor" href="#password-login-of-persons" aria-label="Permalink to “Password login of persons”">​</a></h2><p>Persons log in through your identity provider. On an instance without an identity provider you can let persons log in with their e-mail address and a password instead. This is off on a new instance; permit it explicitly:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># environment of the backend (or --oea.auth.person-password.enabled=true)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OEA_AUTH_PERSONPASSWORD_ENABLED</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># optional: how long an initial password stays valid (1 hour to 30 days, default 72 hours)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OEA_AUTH_PERSONPASSWORD_TEMPORARYPASSWORDVALIDITY</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">PT72H</span></span></code></pre></div><ul><li>An administrator then sets an initial password per person (see <a href="./identity-providers#set-an-initial-password">Identity providers and persons</a>); the person changes it at the first login.</li><li>Administrators can switch password login of persons off and on again with <code>personPasswordLogin</code> of the <a href="./identity-providers#password-policy">password policy</a>. It works only while your setting permits it and their switch is on; without your permission they cannot switch it on.</li><li>Roles with administrative permissions apply to a person only after a login with password and the code of an authenticator app (see <a href="./../usage/login#set-up-a-second-factor">Set up a second factor</a>); after a password login alone they do not apply.</li><li>While password login of persons is not possible, a password login of a person fails like a wrong password, and setting or resetting a password is refused with <code>409</code>.</li></ul><h3 id="password-policy-floors" tabindex="-1">Floors of the password policy <a class="header-anchor" href="#password-policy-floors" aria-label="Permalink to “Floors of the password policy”">​</a></h3><p>Administrators maintain the <a href="./identity-providers#password-policy">password policy</a> through the API. You set the floors it cannot go below; each rule in force is the stricter of your floor and the administrators&#39; value. The defaults switch every rule off:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># minimum length, 12 to 128 (default 12)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OEA_AUTH_PASSWORDPOLICY_MINLENGTH</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">12</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># character types required in any case (default false)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OEA_AUTH_PASSWORDPOLICY_REQUIREUPPERCASE</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OEA_AUTH_PASSWORDPOLICY_REQUIRELOWERCASE</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OEA_AUTH_PASSWORDPOLICY_REQUIREDIGITS</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OEA_AUTH_PASSWORDPOLICY_REQUIRESPECIALCHARS</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">false</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># longest expiry in days, 0 = no ceiling (default 0)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OEA_AUTH_PASSWORDPOLICY_MAXEXPIRYDAYS</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">0</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># smallest history, 0 to 24 (default 0)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OEA_AUTH_PASSWORDPOLICY_MINHISTORYCOUNT</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">0</span></span></code></pre></div><ul><li>A value outside its range stops the backend at startup.</li><li>A raised floor applies at once, also to a policy the administrators stored before.</li><li>The floors apply to the passwords of persons and of the local system admin account.</li></ul><h2 id="verify-the-audit-trail" tabindex="-1">Verify the audit trail <a class="header-anchor" href="#verify-the-audit-trail" aria-label="Permalink to “Verify the audit trail”">​</a></h2><p>Every audit record is a link of a hash chain computed by the database. The verification command recomputes the chain with the read-only role <code>oea_auditor</code>:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oea-backend.jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --oea.audit-verify.url=jdbc:postgresql://db.example.org:5432/oea</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --oea.audit-verify.password=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA_AUDITOR_PASSWORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --checkpoints=/var/log/oea/backend.log</span></span></code></pre></div><p>With Compose: <code>docker compose run --rm migrate audit verify --oea.audit-verify.url=jdbc:postgresql://postgres:5432/oea --oea.audit-verify.password=…</code>. The environment variables <code>OEA_AUDITVERIFY_URL</code> and <code>OEA_AUDITVERIFY_PASSWORD</code> work as well.</p><table tabindex="0"><thead><tr><th>Exit code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>0</code></td><td>chain intact (<code>OK &lt;links&gt; links, head &lt;chain_seq&gt; &lt;hash&gt;</code>)</td></tr><tr><td><code>1</code></td><td>first broken link, missing link, or a database head behind or diverging from a checkpoint (<code>BROKEN …</code>)</td></tr><tr><td><code>2</code></td><td>usage or connection error</td></tr></tbody></table><p><strong>Checkpoints</strong>: the backend appends a checkpoint every 60 minutes (<code>oea.audit.checkpoint-interval</code>, 5–1440 minutes) and at orderly shutdown, and writes a log line <code>event=audit.checkpoint chainSeq=… recordHash=… at=…</code> (in JSON logs a JSON object with these fields, see <a href="#log-format">Log format</a>). Keep the backend log outside the database host (log shipper, journald, SIEM): checkpoints are only as trustworthy as the place they are stored. Pass the log file with <code>--checkpoints=</code> to detect deleted newest records or a restored older backup.</p><h2 id="deactivate-the-local-system-admin-account" tabindex="-1">Deactivate the local system admin account <a class="header-anchor" href="#deactivate-the-local-system-admin-account" aria-label="Permalink to “Deactivate the local system admin account”">​</a></h2><p>After the hand-over of system administration to an IdP group (see <a href="./roles-and-permissions#hand-over-system-administration-to-an-idp-group">Roles and permissions</a>), deactivate the local account of the bootstrapping so that no additional password access stays open. You need the permission <code>auth-config:manage</code>:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/admin/system-admin-account&quot;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">                     # state of the account</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/admin/system-admin-account/deactivate&quot;</span></span></code></pre></div><ul><li>The account&#39;s sessions end at once and its password no longer works; logins through the identity provider are not affected.</li><li>OEA refuses the deactivation with <code>409</code> and problem type <code>urn:oea:problem:last-admin-path</code> as long as no other working path to system administration exists: an active mapping of an active provider to <code>system-admin</code> that has granted the role in at least one login (<code>lastMatchedAt</code>), or a <code>system-admin</code> assignment without <code>validTo</code> of an active person (see <a href="./roles-and-permissions#assign-roles-to-a-single-person">Assign roles to a single person</a>). If you rely on a group, have a member of the group log in shortly before you deactivate the account.</li><li>Both the deactivation and a refused attempt are recorded in the audit trail (<code>system-admin-account.deactivated</code>).</li><li>The same check refuses revoking the last <code>system-admin</code> assignment and deleting, deactivating or retargeting the last working mapping to <code>system-admin</code>. If you still lock yourself out, for example because the members of the group left it at the provider, use the recovery below.</li></ul><h2 id="recover-administrator-access" tabindex="-1">Recover administrator access <a class="header-anchor" href="#recover-administrator-access" aria-label="Permalink to “Recover administrator access”">​</a></h2><p>If nobody can administer the instance any more – the password of the local account is lost or the account is deactivated, and no IdP group mapping to <code>system-admin</code> works – restore the local account with a command inside the backend container. It uses the configuration of the container (database and key-encryption key):</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /app/oea-backend.jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> recover</span></span></code></pre></div><ol><li>Enter the new password twice (12 to 128 characters). It is read from the terminal and never appears on the command line.</li><li>If the setup phase has ended, the command also replaces the second factor: it revokes the old authenticator, shows a new secret and an <code>otpauth</code> URI once, and asks for a code from your authenticator app (three attempts).</li><li>The account is active again, all its sessions are revoked, and its login throttling is cleared. Log in with the new password and, after the setup phase, a code of the new authenticator.</li></ol><p>Without a terminal (<code>docker compose exec -T</code>) the command reads one answer per line from standard input. Exit codes: <code>0</code> recovered, <code>1</code> refused (instance not bootstrapped, wrong codes or input ended – nothing was changed), <code>2</code> usage or connection error.</p><p>The recovery is recorded in the audit trail as <code>system.admin-recovered</code> with source <code>CLI</code>. Neither the password nor the secret is recorded or logged. The secret stays in your terminal&#39;s scrollback, so clear the terminal afterwards. Anyone who can run commands in the backend container can take over the instance this way – the database password and the key in the same container allow that anyway. Treat access to the container as administrator access.</p><h2 id="upgrade-postgresql-to-a-new-major-version" tabindex="-1">Upgrade PostgreSQL to a new major version <a class="header-anchor" href="#upgrade-postgresql-to-a-new-major-version" aria-label="Permalink to “Upgrade PostgreSQL to a new major version”">​</a></h2><p>The Compose setup uses PostgreSQL 18. Data directories are not compatible across major versions, so a major upgrade needs a dump and restore or <code>pg_upgrade</code>:</p><ol><li>Stop the backend, keep PostgreSQL running, and dump the database as superuser: <code>pg_dumpall</code> (roles and data) or <code>pg_dump -Fc oea</code> plus the provisioning script for the roles.</li><li>Start the new PostgreSQL version on an empty volume; the provisioning script creates the roles again.</li><li>Restore the dump, then run the migration step and start the backend.</li></ol><p>Since PostgreSQL 18, the official image keeps its data in <code>/var/lib/postgresql/18/docker</code>; the Compose volume is therefore mounted at <code>/var/lib/postgresql</code>. The minimum supported version stays PostgreSQL 15; the backend checks it at startup.</p>`,53)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};